import { describe, expect, it } from 'vitest';
import {
  RotationDriver,
  TAU,
  normalizeAxis,
  quaternionFromAxisAngle,
  rotateVector,
  wrapAngle,
} from './rotation';

describe('wrapAngle', () => {
  it('maps angles into [0, TAU)', () => {
    expect(wrapAngle(0)).toBe(0);
    expect(wrapAngle(TAU + 1)).toBeCloseTo(1, 10);
    expect(wrapAngle(-Math.PI / 2)).toBeCloseTo((3 * Math.PI) / 2, 10);
  });

  it('falls back to zero for non-finite input', () => {
    expect(wrapAngle(Number.NaN)).toBe(0);
    expect(wrapAngle(Number.POSITIVE_INFINITY)).toBe(0);
  });
});

describe('normalizeAxis', () => {
  it('returns a unit vector', () => {
    expect(normalizeAxis({ x: 0, y: 3, z: 0 })).toEqual({ x: 0, y: 1, z: 0 });
    const diagonal = normalizeAxis({ x: 1, y: 1, z: 0 });
    expect(Math.hypot(diagonal.x, diagonal.y, diagonal.z)).toBeCloseTo(1, 10);
  });

  it('rejects degenerate axes', () => {
    expect(() => normalizeAxis({ x: 0, y: 0, z: 0 })).toThrow(/non-zero length/);
    expect(() => normalizeAxis({ x: Number.NaN, y: 1, z: 0 })).toThrow(/finite vector/);
  });
});

describe('quaternionFromAxisAngle', () => {
  it('rotates a vector a quarter turn around Y', () => {
    const rotation = quaternionFromAxisAngle({ x: 0, y: 1, z: 0 }, Math.PI / 2);
    const rotated = rotateVector(rotation, { x: 1, y: 0, z: 0 });
    expect(rotated.x).toBeCloseTo(0, 10);
    expect(rotated.y).toBeCloseTo(0, 10);
    expect(rotated.z).toBeCloseTo(-1, 10);
  });

  it('keeps vectors on the rotation axis untouched', () => {
    const rotation = quaternionFromAxisAngle({ x: 0, y: 2, z: 0 }, 1.234);
    const rotated = rotateVector(rotation, { x: 0, y: 1, z: 0 });
    expect(rotated.x).toBeCloseTo(0, 10);
    expect(rotated.y).toBeCloseTo(1, 10);
    expect(rotated.z).toBeCloseTo(0, 10);
  });
});

describe('RotationDriver', () => {
  it('advances deterministically for identical step sequences', () => {
    const first = new RotationDriver({ speed: 2, maxStepSeconds: 0.1 });
    const second = new RotationDriver({ speed: 2, maxStepSeconds: 0.1 });
    for (let step = 0; step < 10; step += 1) {
      first.advance(0.05);
      second.advance(0.05);
    }
    expect(first.elapsed).toBeCloseTo(0.5, 10);
    expect(first.angle).toBeCloseTo(1, 10);
    expect(second.angle).toBe(first.angle);
  });

  it('clamps oversized steps and ignores invalid ones', () => {
    const driver = new RotationDriver({ speed: 1, maxStepSeconds: 0.1 });
    driver.advance(5);
    expect(driver.elapsed).toBeCloseTo(0.1, 10);
    driver.advance(-1);
    driver.advance(Number.NaN);
    driver.advance(0);
    expect(driver.elapsed).toBeCloseTo(0.1, 10);
  });

  it('applies the phase offset and restores it on reset', () => {
    const driver = new RotationDriver({ speed: 1, phase: Math.PI });
    expect(driver.angle).toBeCloseTo(Math.PI, 10);
    driver.setElapsed(Math.PI);
    expect(driver.angle).toBeCloseTo(wrapAngle(Math.PI * 2), 10);
    driver.reset();
    expect(driver.elapsed).toBe(0);
    expect(driver.angle).toBeCloseTo(Math.PI, 10);
  });

  it('clamps negative elapsed time to zero', () => {
    const driver = new RotationDriver({ speed: 3 });
    driver.setElapsed(-5);
    expect(driver.elapsed).toBe(0);
    expect(driver.angle).toBe(0);
  });

  it('rejects invalid configuration', () => {
    expect(() => new RotationDriver({ speed: Number.NaN })).toThrow(/finite number/);
    expect(() => new RotationDriver({ speed: 1, maxStepSeconds: 0 })).toThrow(/positive finite/);
  });
});
